SynthDef(\padNeblina, { |out=0, freq=220, amp=0.2, gate=1, cutoff=900|
    var env = EnvGen.kr(Env.adsr(0.8, 0.4, 0.7, 2.0), gate, doneAction: 2);
    var sig = Saw.ar(freq * [0.996, 1.004]).sum * 0.5;
    sig = RLPF.ar(sig, cutoff, 0.35) * env * amp;
    Out.ar(out, Pan2.ar(sig, 0));
}).add;

$logs = Get-ChildItem -Path .\logs -Filter *.log | Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-14) }
foreach ($item in $logs) {
    Compress-Archive -Path $item.FullName -DestinationPath "$($item.FullName).zip" -Force
    Remove-Item $item.FullName
}
